function stripHtml(value=''){return String(value).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/\s+/g,' ').trim()}
function absolute(base, href=''){ try { return new URL(href, base).href; } catch { return base; } }
function parseMarketRows(html, category, sourceUrl){
  const rows = String(html).match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
  const out=[];
  for(const row of rows){
    const cells=(row.match(/<td\b[\s\S]*?<\/td>/gi)||[]).map(stripHtml);
    const rankMatch=row.match(/class=["'][^"']*rank-td[^"']*["'][^>]*>\s*(\d{1,3})/i) || cells.map(x=>x.match(/^(\d{1,3})$/)).find(Boolean);
    const rank=Number(rankMatch?.[1]||0); if(!rank||rank>100)continue;
    const block=row.match(/class=["'][^"']*name-div[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<\/td>/i)?.[1] || row;
    const anchors=[...block.matchAll(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)].map(m=>({href:m[1],text:stripHtml(m[2])})).filter(x=>/[A-Za-z]/.test(x.text));
    let name=anchors[0]?.text||'';
    let ticker=stripHtml(block.match(/class=["'][^"']*(?:company-code|ticker)[^"']*["'][^>]*>([\s\S]*?)<\//i)?.[1]||'');
    if(!ticker&&name){const parts=name.split(' '),last=parts.at(-1);if(/^[A-Z0-9][A-Z0-9.\-]{0,12}$/.test(last)){ticker=last;name=parts.slice(0,-1).join(' ')}}
    if(!name){const likely=cells.find(x=>/[A-Za-z]{3}/.test(x)&&!/^\$/.test(x));name=likely||`Rank ${rank}`}
    const value=(row.match(/\$\s*[\d,.]+\s*[TBM]/i)||[])[0]?.replace(/\s+/g,' ')||'';
    const percentages=[...row.matchAll(/\d+(?:\.\d+)?%/g)].map(m=>m[0]);
    const jurisdiction=cells.at(-1)||'';
    const href=anchors[0]?.href||sourceUrl;
    out.push({id:`${category}-${slug(ticker||name)}`,category,rank,name,ticker,jurisdiction,value,fee:category==='investment-vehicles'?percentages.at(-1)||'':'',metric:category==='companies'?'Market capitalisation':'Vehicle market capitalisation',status:'Verified market snapshot',sourceUrl:absolute(sourceUrl,href),sourceDate:today,evidenceClass:'Verified Market Data',confidence:'Dated market snapshot',established:'The cited ranking reports the displayed market value at the source date.',notEstablished:'Market value is not cash, revenue, profit, personal wealth, voting control or proof of coordinated conduct.',nextResearch:'Open annual reports, ownership filings, voting rights, debt, cash, contracts and regulatory records.'});
  }
  return [...new Map(out.map(x=>[x.rank,x])).values()].sort((a,b)=>a.rank-b.rank).slice(0,100);
}
async function fetchText(url){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),25000);try{const response=await fetch(url,{headers:{'user-agent':'MatrixReprogrammedPublicRecordBot/1.0 (+https://matrixreprogrammed.com/evidence-policy.html)','accept':'text/html,application/xhtml+xml'},signal:controller.signal});if(!response.ok)throw new Error(`${response.status} ${response.statusText}`);return await response.text()}finally{clearTimeout(timeout)}}
function fallbackRows(category, rows){return rows.map((r,i)=>({id:`${category}-${slug(r[1]||r[0])}`,category,rank:i+1,name:r[0],ticker:r[1],jurisdiction:r[2],value:r[3],fee:r[4]||'',metric:category==='companies'?'Market capitalisation':'Vehicle market capitalisation',status:'Partial disclosure ranking',sourceUrl:category==='companies'?'https://companiesmarketcap.com/':'https://companiesmarketcap.com/etfs/largest-etfs-by-marketcap/',sourceDate:today,evidenceClass:'Verified Market Data',confidence:'Fallback snapshot — refresh required',established:'The source identified this entity within the ranking snapshot.',notEstablished:'The fallback does not establish current exact rank, cash ownership, control or performance.',nextResearch:'Refresh the live ranking and open the issuer or company primary disclosures.'}))}
function watchRows(category, names, sourceUrl){return (names||[]).map((name,i)=>({id:`${category}-${slug(name)}`,category,rank:null,name,ticker:'',jurisdiction:'',value:'Not uniformly disclosed',fee:'',metric:'Public-record coverage',status:'Research watch list',sourceUrl,sourceDate:today,evidenceClass:'Research Lead',confidence:'Requires entity-level verification',established:'The entity is a relevant public-record research target for this category.',notEstablished:'Its presence does not establish an exact global rank, asset value, misconduct, coordination or hidden ownership.',nextResearch:'Obtain the latest audited report, regulator filing, official register, procurement record or court filing.'}))}
function managerForVehicle(name=''){if(/^Vanguard/i.test(name))return'Vanguard Group';if(/^iShares/i.test(name))return'BlackRock';if(/^SPDR|State Street/i.test(name))return'State Street Global Advisors';if(/^Invesco/i.test(name))return'Invesco';if(/^Schwab/i.test(name))return'Charles Schwab Investment Management';if(/^JPMorgan/i.test(name))return'JPMorgan Asset Management';if(/^Dimensional/i.test(name))return'Dimensional Fund Advisors';if(/^ProShares/i.test(name))return'ProShares';if(/^VanEck/i.test(name))return'VanEck';return''}
function buildRelationships(registry){const relationships=[];for(const row of registry.records.filter(r=>r.category==='investment-vehicles')){const manager=managerForVehicle(row.name);if(manager)relationships.push({id:`rel-${slug(row.name)}-${slug(manager)}`,from:row.name,to:manager,type:'managed by',sourceUrl:row.sourceUrl,sourceDate:row.sourceDate,evidenceClass:'Institutional Disclosure',established:'The vehicle brand identifies the investment manager or sponsor.',notEstablished:'Management does not mean the manager owns all underlying assets or acts in coordination with issuers.'})}return relationships}
function changesBetween(previous, current){const prior=new Map((previous?.records||[]).map(x=>[x.id,JSON.stringify([x.rank,x.value,x.status,x.sourceDate])]));const now=new Map((current?.records||[]).map(x=>[x.id,JSON.stringify([x.rank,x.value,x.status,x.sourceDate])]));const added=[...now.keys()].filter(k=>!prior.has(k));const removed=[...prior.keys()].filter(k=>!now.has(k));const changed=[...now.keys()].filter(k=>prior.has(k)&&prior.get(k)!==now.get(k));return{added,removed,changed,total:added.length+removed.length+changed.length}}
function pageShell(title,description,body,depth=1){const p='../'.repeat(depth);return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Matrix Reprogrammed</title><meta name="description" content="${esc(description)}"><link rel="stylesheet" href="${p}styles.css"><link rel="stylesheet" href="${p}fixes.css"><link rel="stylesheet" href="${p}reader-experience.css"><link rel="stylesheet" href="${p}money-intelligence.css"><link rel="stylesheet" href="${p}money-expansion.css"></head><body><canvas id="matrix"></canvas><div class="signal-face"></div><div class="veil"></div><div class="page money-shell"><header class="wrap topbar"><a class="brand" href="${p}index.html">MATRIX REPROGRAMMED</a><nav class="nav"><a href="${p}follow-the-money.html">Money Command</a><a href="${p}money-search.html">Money Search</a><a href="${p}money-graph.html">Money Graph</a><a href="${p}making-money.html">Build Wealth</a><a href="${p}evidence-vault.html">Evidence</a></nav></header><main>${body}</main><footer class="footer wrap"><p><strong>MATRIX REPROGRAMMED</strong> — documented ownership and allocation are not automatic proof of operational control or wrongdoing.</p></footer></div><script src="${p}matrix.js"></script></body></html>`}
function categoryPage(category){return pageShell(category.title,category.description,`<section class="hero wrap"><div class="money-kicker">${esc(category.rankingStatus)} · target coverage ${category.target}</div><h1>${esc(category.title.toUpperCase())}</h1><p class="lead">${esc(category.description)}</p><div class="cta-row"><a class="btn" href="#registry">Open registry</a><a class="btn alt" href="${esc(category.sourceUrl)}" rel="noopener noreferrer">Primary ranking route</a><a class="btn alt" href="../follow-the-money.html">All money systems</a></div><aside class="money-warning"><strong>Evidence boundary:</strong> exact rank is shown only when a dated source supports it. AUM is client capital, market capitalisation is not cash, donations do not prove corruption, and association does not prove coordinated control.</aside></section><section id="registry" class="section wrap"><div class="money-category-status" id="money-category-status">Loading public-record registry…</div><div class="money-toolbar"><label>Search<input id="money-category-search" type="search" placeholder="Name, ticker, country or evidence"></label><label>Status<select id="money-category-filter"><option value="">All statuses</option></select></label><button class="btn alt" id="money-category-reset" type="button">Reset</button></div><div class="money-table-wrap"><table><thead><tr><th>Rank</th><th>Entity</th><th>Value / measure</th><th>Jurisdiction</th><th>Evidence</th><th>Source</th></tr></thead><tbody id="money-category-body"><tr><td colspan="6">Loading…</td></tr></tbody></table></div><div id="money-category-pagination" class="money-pagination"></div></section><section class="section wrap split"><article class="money-card"><h2>What the record establishes</h2><p id="money-category-established">Open a record to see its exact evidence boundary.</p></article><article class="money-card redline"><h2>What it does not establish</h2><p id="money-category-not-established">Common ownership, investment exposure or funding does not by itself establish coordination, intent or wrongdoing.</p></article></section><script>window.MATRIX_MONEY_CATEGORY=${JSON.stringify(category.id)};</script><script src="../money-category.js"></script>`,1)}
function guideSections(method){const a=archetypes[method.archetype]||archetypes.service;const e=method.economics;const contribution=Math.max(0,e.price-e.variableCost),breakEven=contribution>0?Math.ceil(e.fixedMonthly/contribution):0,gross=e.price*e.monthlySales,variable=e.variableCost*e.monthlySales,operating=gross-variable-e.fixedMonthly;const sources=sourceByArchetype[method.archetype]||sourceByArchetype.service;return [
  {title:'Executive summary',lines:[`${method.title} is modelled as: ${method.offer}.`,`Typical starting capital band: ${method.capital}. Expected time to first income or result: ${method.firstIncome}.`,`Risk: ${method.risk}. Complexity: ${method.complexity}. These are broad planning bands, not probabilities or guarantees.`]},
  {title:'Who this is for',lines:[`Best suited to someone able to serve or access: ${method.customer}.`,`Core capabilities: ${a.skills.join('; ')}.`,`Avoid or delay this route when essential bills, legal requirements, debt service, safety, liquidity or family commitments cannot be protected.`]},
  {title:'How money is generated',lines:[method.offer,`The paying counterparty or economic source is: ${method.customer}.`,`Profit or retained value exists only after variable costs, fixed costs, tax, financing, returns, failures and owner labour are counted.`]},
  {title:'Starting requirements',lines:[`Capital: ${method.capital}.`,`Skills: ${a.skills.join('; ')}.`,`Tools: ${a.tools.join('; ')}.`,`Verify registrations, licences, insurance, consumer rules, data protection, tax and sector-specific restrictions before trading or investing.`]},
  {title:'Illustrative unit economics',lines:[e.price?`Illustrative price or monthly value per unit: EUR ${e.price}.`:'No sales price is assumed for this financial method.',e.variableCost?`Illustrative variable cost per unit: EUR ${e.variableCost}.`:'Variable unit cost is not modelled.',e.fixedMonthly?`Illustrative monthly fixed cost: EUR ${e.fixedMonthly}.`:'Fixed monthly cost is assumed to be minimal or account-specific.',e.monthlySales>1?`Illustrative monthly volume: ${e.monthlySales}.`:'This method is evaluated as an account, asset or single acquisition rather than repeated monthly sales.',e.price?`Illustrative monthly revenue: EUR ${gross}; contribution before fixed costs: EUR ${gross-variable}; operating surplus before tax and owner labour: EUR ${operating}.`:'Returns, rates and asset prices are intentionally not forecast.',breakEven?`Illustrative break-even volume: ${breakEven} units per month.`:'Break-even must be calculated from the actual product, account or transaction.','All figures are assumptions for planning. Replace them with verified local quotes and conservative scenarios.']},
  {title:'First 24 hours',lines:a.first24},{title:'First seven days',lines:a.first7},{title:'First 30 days',lines:a.first30},{title:'First 90 days',lines:a.first90},
  {title:'First year roadmap',lines:['Quarter 1: prove demand, suitability or operational feasibility with the smallest responsible test.','Quarter 2: improve unit economics, documentation, compliance and repeatability.','Quarter 3: reduce concentration, strengthen reserves and build a second acquisition or distribution route.','Quarter 4: complete a full profit, cash-flow, tax, risk and continuation review before scaling.']},
  {title:'Customer or capital acquisition',lines:[a.acquisition,'Record outreach volume, response, conversion, acquisition cost, retention and cash collection. For investments, record contribution, fees, allocation and reason for ownership instead.']},
  {title:'Tools and templates',lines:[...a.tools,'Budget and cash-flow tracker','Pricing or suitability calculator','Break-even or loss-capacity calculation','Weekly scorecard','Risk register','90-day action plan']},
  {title:'Failure analysis',lines:a.failures.map(x=>`Risk: ${x}. Mitigation: verify it in writing before committing more money.`)},
  {title:'Decision test',lines:['START NOW only when the smallest safe test is affordable and lawful.','LEARN FIRST when the model is understood but the required skill, evidence or compliance is missing.','TEST CHEAPLY when demand or suitability is uncertain.','AVOID when loss could threaten housing, health, tax compliance or essential obligations.','SEEK PROFESSIONAL ADVICE for contracts, tax, regulated investments, property, borrowing, employment law or complex entities.']},
  {title:'Primary research routes',lines:sources.flatMap(([name,url])=>[`${name}: ${url}`])},
  {title:'Evidence and legal boundary',lines:['This material is educational and based on public information. It is not personalised financial, investment, legal or tax advice.','Costs, taxes, laws, returns and risks vary by location and personal circumstances. Verify current rules and consult an appropriately qualified professional before committing significant money or signing contracts.','No guaranteed returns, fake case studies, hidden ownership, tax evasion, borrowed-money speculation or unsupported income claims are permitted.']}
]}
function wrapText(value,width=88){const words=String(value||'').replace(/[^\x20-\x7E]/g,' ').replace(/\s+/g,' ').trim().split(' '),lines=[];let line='';for(const word of words){const next=line?`${line} ${word}`:word;if(next.length<=width)line=next;else{if(line)lines.push(line);line=word}}if(line)lines.push(line);return lines}
function pdfEscape(value){return String(value||'').replace(/[^\x20-\x7E]/g,' ').replace(/[\\()]/g,m=>`\\${m}`)}
function makePdf(title,sections){const logical=[];for(const section of sections){logical.push({kind:'heading',text:section.title.toUpperCase()});for(const item of section.lines||[])for(const line of wrapText(item))logical.push({kind:'body',text:line});logical.push({kind:'space',text:''})}const pages=[];let current=[],used=0;for(const item of logical){const cost=item.kind==='heading'?2:1;if(used+cost>42){pages.push(current);current=[];used=0}current.push(item);used+=cost}if(current.length)pages.push(current);const objects=[];const add=x=>(objects.push(x),objects.length);const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),bold=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'),pageIds=[],contentIds=[];pages.forEach((items,pageIndex)=>{let stream=`q\n0.03 0.035 0.045 rg\n0 752 595 90 re f\nQ\nBT\n1 1 1 rg\n/F2 17 Tf\n42 812 Td\n(${pdfEscape(title).slice(0,90)}) Tj\n/F1 8 Tf\n0 -22 Td\n(MATRIX REPROGRAMMED | PRACTICAL WEALTH MANUAL) Tj\nET\nq\n0.76 0.58 0.18 rg\n42 744 511 3 re f\nQ\nBT\n0.08 0.08 0.08 rg\n/F1 9 Tf\n42 720 Td\n`;let first=true;for(const item of items){if(!first)stream+=`0 -${item.kind==='heading'?19:item.kind==='space'?8:14} Td\n`;first=false;stream+=item.kind==='heading'?'/F2 11 Tf\n':'/F1 9 Tf\n';if(item.kind!=='space')stream+=`(${pdfEscape(item.text).slice(0,125)}) Tj\n`}stream+=`ET\nq\n0.92 0.92 0.92 rg\n0 0 595 34 re f\nQ\nBT\n0.2 0.2 0.2 rg\n/F1 8 Tf\n42 13 Td\n(Educational guide | checked ${today} | page ${pageIndex+1} of ${pages.length}) Tj\nET`;contentIds.push(add(`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`));pageIds.push(null)});const pagesId=add('');for(let i=0;i<pages.length;i++)pageIds[i]=add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R /F2 ${bold} 0 R >> >> /Contents ${contentIds[i]} 0 R >>`);objects[pagesId-1]=`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] >>`;const catalog=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);let out='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(Buffer.byteLength(out));out+=`${i+1} 0 obj\n${o}\nendobj\n`});const xref=Buffer.byteLength(out);out+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(n=>`${String(n).padStart(10,'0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length+1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(out,'binary')}
