write('making-money-methods.js',`(()=>{'use strict';const grid=document.querySelector('#wealth-method-grid');if(!grid)return;const search=document.querySelector('#wealth-method-search'),capital=document.querySelector('#wealth-method-capital'),risk=document.querySelector('#wealth-method-risk'),reset=document.querySelector('#wealth-method-reset'),form=document.querySelector('#wealth-plan-form'),result=document.querySelector('#wealth-plan-result');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let methods=[];function capBand(text){const nums=(text.match(/\d+/g)||[]).map(Number),max=Math.max(...nums,0);return max<=500?'low':max<=10000?'medium':'high'}function selected(){const q=search.value.trim().toLowerCase();return methods.filter(x=>(!q||[x.title,x.offer,x.customer,x.archetype].join(' ').toLowerCase().includes(q))&&(!capital.value||capBand(x.capital)===capital.value)&&(!risk.value||x.risk.toLowerCase()===risk.value.toLowerCase()))}function render(list=selected()){grid.innerHTML=list.map(x=>'<article class="money-card method-card"><div class="method-meta"><span>'+esc(x.capital)+'</span><span>'+esc(x.firstIncome)+'</span><span>'+esc(x.risk)+' risk</span></div><h3>'+esc(x.title)+'</h3><p>'+esc(x.offer)+'</p><p><strong>Customer / source:</strong> '+esc(x.customer)+'</p><div class="cta-row"><a class="btn" href="making-money/guides/'+esc(x.id)+'.html">Open Manual</a><a class="btn alt" href="downloads/wealth-guides/'+esc(x.id)+'.pdf">PDF</a></div></article>').join('')||'<p>No matching method.</p>'}fetch('data/wealth-methods.json',{cache:'no-store'}).then(r=>r.json()).then(d=>{methods=d.methods||[];render()});[search,capital,risk].forEach(x=>x.addEventListener('input',()=>render()));reset.onclick=()=>{search.value='';capital.value='';risk.value='';render()};form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form),budget=Number(data.get('capital')||0),hours=Number(data.get('hours')||0),tol=String(data.get('risk')||'Moderate').toLowerCase(),rank={low:1,moderate:2,high:3,'very high':4},maxRisk=tol==='low'?1:tol==='high'?3:2;const shortlist=methods.filter(m=>{const band=capBand(m.capital),affordable=budget>=10000?true:budget>=500?band!=='high':band==='low';return affordable&&(rank[m.risk.toLowerCase()]||4)<=maxRisk+(hours>=20?1:0)}).slice(0,6);result.innerHTML='<strong>Shortlist for '+esc(data.get('country'))+':</strong><ul>'+shortlist.map(x=>'<li><a href="making-money/guides/'+esc(x.id)+'.html">'+esc(x.title)+'</a> — '+esc(x.capital)+', '+esc(x.risk)+' risk.</li>').join('')+'</ul><small>Verify local law, tax, licences, finance and suitability before acting. Inputs were processed only in this browser.</small>';render(shortlist)})})();`);
