async function build(){
  ensure('data/history/money-intelligence');ensure('follow-the-money');ensure('making-money/guides');ensure('downloads/wealth-guides');
  const previous=readJson('data/money-intelligence-registry.json',{records:[],relationships:[]});
  let companies=previous.records?.filter(x=>x.category==='companies')||[],vehicles=previous.records?.filter(x=>x.category==='investment-vehicles')||[];
  if(process.env.MATRIX_MONEY_REFRESH==='1'){
    try{companies=parseMarketRows(await fetchText('https://companiesmarketcap.com/'),'companies','https://companiesmarketcap.com/')}catch(error){console.warn(`Company ranking refresh failed: ${error.message}`)}
    try{vehicles=parseMarketRows(await fetchText('https://companiesmarketcap.com/etfs/largest-etfs-by-marketcap/'),'investment-vehicles','https://companiesmarketcap.com/etfs/largest-etfs-by-marketcap/')}catch(error){console.warn(`Investment vehicle refresh failed: ${error.message}`)}
  }
  if(!companies.length)companies=fallbackRows('companies',companyFallback);if(!vehicles.length)vehicles=fallbackRows('investment-vehicles',vehicleFallback);
  if(process.env.MATRIX_MONEY_REQUIRE_LIVE==='1'&&(companies.length<100||vehicles.length<100))throw new Error(`Live money ranking incomplete: companies=${companies.length}, investmentVehicles=${vehicles.length}`);
  const records=[...companies,...vehicles];for(const category of categories.filter(c=>!['companies','investment-vehicles'].includes(c.id)))records.push(...watchRows(category.id,watchlists[category.id],category.sourceUrl));
  const registry={version:2,updated:sourceDate,methodology:'Every record states what the source establishes and what it does not establish. Exact rankings are not invented where public disclosure is incomplete.',categories:categories.map(c=>({...c,coverage:records.filter(r=>r.category===c.id).length})),records,relationships:[],sources:[...new Map(categories.map(c=>[c.sourceUrl,{name:c.title,url:c.sourceUrl,checked:today}])).values()]};registry.relationships=buildRelationships(registry);registry.changes=changesBetween(previous,registry);writeJson('data/money-intelligence-registry.json',registry);writeJson(`data/history/money-intelligence/${today}.json`,registry);
  const searchRecords=records.map(r=>({...r,categoryTitle:categories.find(c=>c.id===r.category)?.title||r.category,route:categories.find(c=>c.id===r.category)?.route||'follow-the-money.html',search:[r.name,r.ticker,r.jurisdiction,r.value,r.status,r.evidenceClass,r.category].join(' ').toLowerCase()}));writeJson('data/money-search-index.json',{updated:sourceDate,records:searchRecords});
  const summary={updated:sourceDate,title:'Money Intelligence Brief Feed',coverage:registry.categories.map(c=>({category:c.title,route:c.route,coverage:c.coverage,target:c.target,status:c.rankingStatus})),changes:registry.changes,topCompanies:companies.slice(0,10),topInvestmentVehicles:vehicles.slice(0,10),boundary:'Market value, assets under management, grants, contracts and political spending are different measures. None automatically establish cash ownership, operational control, coordination or wrongdoing.',routes:['follow-the-money.html','money-search.html','money-graph.html','making-money.html#wealth-method-library']};writeJson('data/money-intelligence-brief-feed.json',summary);
  writeJson('data/wealth-methods.json',{version:2,updated:sourceDate,disclaimer:'Educational information only. Not personalised financial, investment, legal or tax advice.',methods:methodRows.map(m=>({...m,customer:m.customer||m.offer,sources:sourceByArchetype[m.archetype]||[]}))});
  for(const category of categories)write(category.route,categoryPage(category));
  for(const method of methodRows){const sections=guideSections(method);write(`making-money/guides/${method.id}.html`,guidePage(method));fs.writeFileSync(file(`downloads/wealth-guides/${method.id}.pdf`),makePdf(method.title,sections))}
  writeJson('downloads/wealth-guides/index.json',{updated:sourceDate,count:methodRows.length,guides:methodRows.map(m=>({slug:m.id,title:m.title,url:`downloads/wealth-guides/${m.id}.pdf`,html:`making-money/guides/${m.id}.html`,capital:m.capital,risk:m.risk,firstIncome:m.firstIncome}))});
  makeSharedAssets();patchFollowHub(registry);patchMakingMoney();patchHomepage();patchSupportingPages();patchWorkerAssets();
  console.log(`Money intelligence expansion built: ${records.length} records, ${categories.length} categories, ${registry.relationships.length} relationships and ${methodRows.length} operational guides.`)
}
build().catch(error=>{console.error(error.stack||error);process.exit(1)});
